UPDATE projects SET images = '["https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/1785225169394-250938775.png","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/1785225169295-375624683.png","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/1785225169344-190570374.png","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/1785225169367-222471526.png","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/1785225169320-757856043.png","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/1785225169227-411774767.png","https://tofmglzhxvdozgnwmvhb.supabase.co/storage/v1/object/public/images/1785225169271-859573308.png"]' WHERE slug = 'gold-gym';
SELECT (SELECT count(*) FROM projects) AS projects, (SELECT count(*) FROM blog_posts) AS blog_posts, (SELECT count(*) FROM storage.objects WHERE bucket_id = 'images') AS recovered_images, (SELECT count(*) FROM pg_tables WHERE schemaname = 'public' AND rowsecurity) AS protected_tables;
